function updateDate(){
  const now=new Date();
  const fmt=d=>d.toLocaleDateString('en-IN',{day:'2-digit',month:'short',year:'numeric'});
  document.getElementById('liveDateBadge').textContent=fmt(now);
  const a=new Date(now); a.setDate(now.getDate()-10);
  const b=new Date(now); b.setDate(now.getDate()+10);
  document.getElementById('kpi-from').textContent=fmt(a);
  document.getElementById('kpi-to').textContent=fmt(b);
}
updateDate();

// ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ PAGE NAVIGATION ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬
function showPage(id,el){
  const pagePermissionMap = {
    dashboard:'dashboard',
    clients:'clients.view',
    quotation:'quotation.request',
    billing:'billing',
    reports:'reports',
    github:'guide'
  };
  const requiredPermission=pagePermissionMap[id];
  const hasAccess = !requiredPermission
    || userHasPermission(requiredPermission)
    || (id==='clients' && hasAnyClientAccess())
    || (id==='quotation' && hasQuotationAccess());
  if(!hasAccess){
    showToast('Access denied');
    return;
  }
  document.querySelectorAll('.page').forEach(p=>p.classList.remove('active-page'));
  document.getElementById('page-'+id).classList.add('active-page');
  document.querySelectorAll('.nav-icon').forEach(n=>n.classList.remove('active'));
  if(el) el.classList.add('active');
  if(id==='clients') renderClientsTable();
  if(id==='quotation') renderQuotationPage();
  if(id==='billing') renderBillingPage();
}
function showSubTab(el){
  document.querySelectorAll('.nav-tab').forEach(t=>t.classList.remove('active'));
  el.classList.add('active');
}
function switchTab(tab,el){
  currentTab=tab;
  document.querySelectorAll('.prod-tab').forEach(b=>b.classList.remove('active'));
  if(el) el.classList.add('active');
  renderAll();
  if(document.getElementById('page-clients').classList.contains('active-page')) renderClientsTable();
  if(document.getElementById('page-billing').classList.contains('active-page')) renderBillingPage();
}

function openAddClientFromSidebar(){
  if(!requirePermission('clients.add')) return;
  closeClientsFlyout();
  showPage('clients', document.getElementById('clientsNavIcon'));
  window.setTimeout(()=>{
    openAddModal();
  }, 60);
}
function openProformaInvoiceFromSidebar(){
  if(!requirePermission('clients.invoice')) return;
  closeClientsFlyout();
  showPage('clients', document.getElementById('clientsNavIcon'));
  window.setTimeout(()=>{
    openInvoiceBrowser();
  }, 60);
}
function openPiHistoryFromSidebar(){
  if(!requirePermission('clients.invoice')) return;
  closeClientsFlyout();
  showPage('clients', document.getElementById('clientsNavIcon'));
  window.setTimeout(()=>{
    openSavedInvoicesModal();
  }, 60);
}

