function syncInvoicePreview(){
  const preview=document.getElementById('invoicePreview');
  if(!preview) return;
  const data=getInvoiceFormData();
  currentInvoiceDraft={...currentInvoiceDraft,...data};
  preview.innerHTML=buildInvoicePreviewHtml(data);
  fitInvoicePreview('invoicePreviewWrap','invoicePreviewStage','invoicePreview');
}
function saveInvoiceDraft(){
  const data=getInvoiceFormData();
  if(!data.invoiceNo){ showToast('Please enter the Proforma Invoice number'); return false; }
  if(!data.recipientName){ showToast('Please enter the recipient name'); return false; }
  if(!data.items.length){ showToast('Add at least one description row'); return false; }
  const invoices=getStoredInvoices();
  const index=invoices.findIndex(item=>item.id===data.id);
  if(index>=0 && !currentUser?.isAdmin){
    showToast('Only admin can modify saved PI invoices');
    return false;
  }
  if(index>=0) invoices[index]=data; else invoices.push(data);
  setStoredInvoices(invoices);
  const company=getInvoiceCompanyById(data.companyId);
  const serial=extractInvoiceSerial(data.invoiceNo, company);
  if(company && serial){
    const companies=getStoredInvoiceCompanies();
    const companyIndex=companies.findIndex(item=>item.id===company.id);
    if(companyIndex>=0 && Number(companies[companyIndex].nextSerial || 1) <= serial){
      companies[companyIndex]={ ...companies[companyIndex], nextSerial: serial + 1 };
      setStoredInvoiceCompanies(companies);
      if(currentInvoiceCompanySettingsId===company.id) loadInvoiceCompanySettingsForm(company.id);
      populateInvoiceCompanyOptions(data.companyId);
    }
  }
  currentInvoiceId=data.id;
  currentInvoiceDraft=data;
  populateInvoiceSwitcher(data.opid, data.id);
  const select=document.getElementById('invoiceSelect');
  if(select) select.value=data.id;
  document.getElementById('invoiceDraftMeta').textContent=`${data.product} - ${data.invoiceNo}`;
  showToast('Proforma invoice saved');
  return true;
}
function handleInvoiceImageUpload(event,type){
  const file=event.target.files?.[0];
  if(!file) return;
  const reader=new FileReader();
  reader.onload=()=>{
    currentInvoiceDraft=currentInvoiceDraft || {};
    if(type==='qr') currentInvoiceDraft.qrData=reader.result;
    syncInvoicePreview();
  };
  reader.readAsDataURL(file);
}
function fitInvoicePreview(wrapId='invoicePreviewWrap', stageId='invoicePreviewStage', sheetId='invoicePreview'){
  const wrap=document.getElementById(wrapId);
  const stage=document.getElementById(stageId);
  const sheet=document.getElementById(sheetId);
  if(!wrap || !stage || !sheet) return;
  const naturalWidth=794;
  const naturalHeight=sheet.offsetHeight || 1123;
  const scale=Math.min(1, Math.max(0.42, (wrap.clientWidth - 24) / naturalWidth));
  sheet.style.transform=`scale(${scale})`;
  stage.style.height=`${naturalHeight * scale}px`;
}
async function downloadInvoicePdf(){
  const preview=document.getElementById('invoicePreview');
  if(!preview) return;
  if(!saveInvoiceDraft()) return;
  if(typeof html2canvas==='undefined' || !window.jspdf?.jsPDF){ window.print(); return; }
  const canvas=await html2canvas(preview,{ scale:2, useCORS:true, backgroundColor:'#ffffff' });
  const image=canvas.toDataURL('image/png');
  const { jsPDF } = window.jspdf;
  const pdf=new jsPDF('p','pt','a4');
  const width=pdf.internal.pageSize.getWidth();
  const height=(canvas.height * width) / canvas.width;
  pdf.addImage(image,'PNG',0,0,width,height);
  const fileLabel=[currentInvoiceDraft?.recipientName || 'Client', currentInvoiceDraft?.invoiceNo || 'proforma-invoice']
    .join(' - ')
    .replace(/[\\/:*?"<>|]+/g,'-');
  const fileName=fileLabel;
  pdf.save(`${fileName}.pdf`);
  showToast('PDF downloaded');
}
window.addEventListener('resize', fitInvoicePreview);

