function resetQuotationFieldForm(){ currentQuotationFieldEditingId=null; const title=document.getElementById('quotationFieldFormTitle'); if(title) title.textContent='New Field'; ['quotationFieldLabel','quotationFieldPlaceholder','quotationFieldOptions'].forEach(id=>{ const element=document.getElementById(id); if(element) element.value=''; }); const type=document.getElementById('quotationFieldType'); const required=document.getElementById('quotationFieldRequired'); if(type) type.value='text'; if(required) required.checked=false; handleQuotationFieldTypeChange(); }
function handleQuotationFieldTypeChange(){ const type=document.getElementById('quotationFieldType')?.value || 'text'; const wrap=document.getElementById('quotationFieldOptionsWrap'); if(wrap) wrap.hidden=type!=='dropdown'; }
function editQuotationField(fieldId){ const field=getStoredQuotationFields().find(item=>item.id===fieldId); if(!field) return; currentQuotationFieldEditingId=field.id; document.getElementById('quotationFieldFormTitle').textContent='Edit Field'; document.getElementById('quotationFieldLabel').value=field.label; document.getElementById('quotationFieldType').value=field.type; document.getElementById('quotationFieldPlaceholder').value=field.placeholder || ''; document.getElementById('quotationFieldRequired').checked=!!field.required; document.getElementById('quotationFieldOptions').value=(field.options || []).join('\n'); handleQuotationFieldTypeChange(); }
function saveQuotationFieldDefinition(){ const label=document.getElementById('quotationFieldLabel')?.value.trim(); const type=document.getElementById('quotationFieldType')?.value || 'text'; const placeholder=document.getElementById('quotationFieldPlaceholder')?.value || ''; const required=!!document.getElementById('quotationFieldRequired')?.checked; const optionsRaw=document.getElementById('quotationFieldOptions')?.value || ''; if(!label){ showToast('Field label is required'); return; } const options=type==='dropdown' ? optionsRaw.split('\n').map(option=>option.trim()).filter(Boolean) : []; if(type==='dropdown' && !options.length){ showToast('Add at least one dropdown option'); return; } const fields=getStoredQuotationFields(); const field={ id:currentQuotationFieldEditingId || makeQuotationFieldId(label), label, type, required, placeholder, options, order:currentQuotationFieldEditingId ? (fields.find(item=>item.id===currentQuotationFieldEditingId)?.order || fields.length + 1) : fields.length + 1 }; const nextFields=currentQuotationFieldEditingId ? fields.map(item=>item.id===currentQuotationFieldEditingId ? field : item) : [...fields, field]; setStoredQuotationFields(nextFields.sort((a,b)=>a.order-b.order).map((item,index)=>({ ...item, order:index + 1 }))); renderQuotationFieldList(); resetQuotationFieldForm(); showToast('Quotation form updated'); }
function moveQuotationField(fieldId, direction){ const fields=getStoredQuotationFields(); const index=fields.findIndex(field=>field.id===fieldId); const target=index + direction; if(index<0 || target<0 || target>=fields.length) return; const clone=[...fields]; [clone[index], clone[target]]=[clone[target], clone[index]]; setStoredQuotationFields(clone.map((field,idx)=>({ ...field, order:idx + 1 }))); renderQuotationFieldList(); }
function deleteQuotationField(fieldId){ const fields=getStoredQuotationFields(); if(fields.length===1){ showToast('At least one field is required'); return; } const next=fields.filter(field=>field.id!==fieldId).map((field,index)=>({ ...field, order:index + 1 })); setStoredQuotationFields(next); if(currentQuotationFieldEditingId===fieldId) resetQuotationFieldForm(); renderQuotationFieldList(); showToast('Field deleted'); }
function openQuotationDetailModal(requestId){ const requests=getStoredQuotationRequests(); const request=requests.find(item=>item.id===requestId); if(!request) return; currentQuotationRequestId=requestId; if(currentUser?.isAdmin) request.adminUnread=false; else request.salesUnreadFor=(request.salesUnreadFor || []).filter(userId=>userId!==normalizeUserId(currentUser?.userId)); setQuotationRequestsAndRefresh(requests); const body=document.getElementById('quotationDetailBody'); const title=document.getElementById('quotationDetailTitle'); if(title) title.textContent=`${request.requestId} • ${getQuotationClientName(request)}`; if(body){ const fields=getStoredQuotationFields(); body.innerHTML=`<div class="quotation-request-meta"><div class="quotation-meta-card"><div class="k">Request ID</div><div class="v">${escapeHtml(request.requestId)}</div></div><div class="quotation-meta-card"><div class="k">Sales Person</div><div class="v">${escapeHtml(request.salesPerson)}</div></div><div class="quotation-meta-card"><div class="k">Submitted</div><div class="v">${escapeHtml(formatDateTime(request.createdAt))}</div></div><div class="quotation-meta-card"><div class="k">Status</div><div class="v"><span class="quotation-chip ${quotationStatusClass(request.status)}">${escapeHtml(request.status)}</span></div></div></div><div class="quotation-detail-grid"><div class="quotation-detail-card"><div class="quotation-section-title" style="margin-bottom:10px">Request Details</div><div class="quotation-request-values">${fields.map(field=>{ const raw=request.values?.[field.id]; const value=formatQuotationFieldValue(field, raw); return `<div class="quotation-request-value ${(field.type==='textarea' || field.type==='pricing') ? 'full' : ''}"><div class="k">${escapeHtml(field.label)}</div><div class="v">${value}</div></div>`; }).join('')}</div><div class="quotation-section-title" style="margin:18px 0 10px">Correction History</div><div class="quotation-history">${request.correctionHistory?.length ? request.correctionHistory.map(item=>`<div class="quotation-history-item"><div class="top"><span>${escapeHtml(item.by)}</span><span>${escapeHtml(formatDateTime(item.at))}</span></div><div class="body">${nl2br(item.remarks)}</div></div>`).join('') : '<div class="quotation-empty" style="padding:18px">No correction remarks yet.</div>'}</div></div><div class="quotation-detail-card"><div class="quotation-section-title" style="margin-bottom:10px">Quotation PDF</div>${request.quotationPdfData ? `<div class="quotation-empty" style="padding:18px 0 8px;text-align:left">Quotation is ready for preview. Open it in read-only mode to review before approving.</div>` : '<div class="quotation-empty">No quotation PDF uploaded yet.</div>'}<div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:14px">${request.quotationPdfData ? `<button class="quotation-action-btn secondary" type="button" onclick="openQuotationPreviewModal('${request.id}')">View Quotation</button>` : ''}${currentUser?.isAdmin ? `<button class="quotation-action-btn primary" type="button" onclick="openQuotationUploadModal('${request.id}')">${request.quotationPdfData ? 'Upload Revised PDF' : 'Upload PDF'}</button>` : ''}${!currentUser?.isAdmin && ['Sent for Sales Approval','Revised Quotation Sent'].includes(request.status) ? `<button class="quotation-action-btn primary" type="button" onclick="approveQuotationRequest('${request.id}')">Approve Quotation</button><button class="quotation-action-btn warn" type="button" onclick="openQuotationCorrectionModal('${request.id}')">Request Correction</button>` : ''}</div>${!currentUser?.isAdmin && request.quotationPdfData ? `<div class="quotation-empty" style="padding:14px 0 0;text-align:left">Quotation has been prepared. Please review it from View Quotation, then approve or request correction.</div>` : ''}<div class="quotation-section-title" style="margin:18px 0 10px">Activity</div><div class="quotation-history">${(request.history || []).slice().reverse().map(item=>`<div class="quotation-history-item"><div class="top"><span>${escapeHtml(item.status)}</span><span>${escapeHtml(formatDateTime(item.at))}</span></div><div class="body">${nl2br(item.note || item.by)}</div></div>`).join('')}</div></div></div>`; } document.getElementById('quotationDetailBackdrop')?.classList.add('open'); }
function openQuotationPreviewModal(requestId){ const request=getStoredQuotationRequests().find(item=>item.id===requestId); if(!request?.quotationPdfData) return; currentQuotationPreviewRequestId=requestId; const frame=document.getElementById('quotationPreviewFrame'); const title=document.getElementById('quotationPreviewTitle'); const actions=document.getElementById('quotationPreviewActions'); if(frame){ frame.removeAttribute('src'); frame.setAttribute('src', getQuotationPreviewSrc(request.quotationPdfData)); } if(title) title.textContent=`${request.requestId} • ${getQuotationClientName(request)}`; if(actions){ actions.innerHTML=`<button class="btn-cancel" type="button" onclick="closeQuotationPreviewModal()">Close</button>${!currentUser?.isAdmin && ['Sent for Sales Approval','Revised Quotation Sent'].includes(request.status) ? `<button class="btn-save" type="button" onclick="approveQuotationFromPreview('${request.id}')">Approve Quotation</button><button class="quotation-action-btn warn" type="button" onclick="requestQuotationCorrectionFromPreview('${request.id}')">Request Correction</button>` : ''}`; } document.getElementById('quotationPreviewBackdrop')?.classList.add('open'); }
function closeQuotationPreviewModal(){ document.getElementById('quotationPreviewBackdrop')?.classList.remove('open'); const frame=document.getElementById('quotationPreviewFrame'); if(frame) frame.setAttribute('src',''); currentQuotationPreviewRequestId=null; }
function approveQuotationFromPreview(requestId){ closeQuotationPreviewModal(); approveQuotationRequest(requestId); }
function requestQuotationCorrectionFromPreview(requestId){ closeQuotationPreviewModal(); openQuotationCorrectionModal(requestId); }
function closeQuotationDetailModal(){ document.getElementById('quotationDetailBackdrop')?.classList.remove('open'); }
function openQuotationUploadModal(requestId){ if(!currentUser?.isAdmin) return; currentQuotationUploadRequestId=requestId; const request=getStoredQuotationRequests().find(item=>item.id===requestId); const file=document.getElementById('quotationPdfFile'); const note=document.getElementById('quotationUploadNote'); const select=document.getElementById('quotationApprovalUser'); const existingWrap=document.getElementById('quotationExistingPdfWrap'); const existingName=document.getElementById('quotationExistingPdfName'); if(file) file.value=''; if(note) note.value=''; if(select){ const users=getQuotationEligibleSalesUsers(); const defaultUserId=request?.approvalSalesUserId || request?.salesUserId || ''; select.innerHTML=users.map(user=>`<option value="${escapeHtml(user.userId)}" ${normalizeUserId(user.userId)===normalizeUserId(defaultUserId)?'selected':''}>${escapeHtml(user.userId)}</option>`).join(''); } if(existingWrap) existingWrap.hidden=!request?.quotationPdfName; if(existingName) existingName.textContent=request?.quotationPdfName || 'No file'; document.getElementById('quotationUploadBackdrop')?.classList.add('open'); }
function closeQuotationUploadModal(){ document.getElementById('quotationUploadBackdrop')?.classList.remove('open'); }
async function saveQuotationPdfUpload(){ if(!currentUser?.isAdmin || !currentQuotationUploadRequestId) return; const fileInput=document.getElementById('quotationPdfFile'); const note=document.getElementById('quotationUploadNote')?.value.trim() || ''; const file=fileInput?.files?.[0]; if(!file){ showToast('Select a quotation PDF to upload'); return; } if(file.type && file.type!=='application/pdf'){ showToast('Please upload a PDF file'); return; } const pdfData=await readFileAsDataUrl(file); const requests=getStoredQuotationRequests().map(request=>{ if(request.id!==currentQuotationUploadRequestId) return request; const nextStatus='Quotation Uploaded'; return { ...request, quotationPdfData:pdfData, quotationPdfName:file.name, quotationPdfUploadedAt:new Date().toISOString(), status:nextStatus, updatedAt:new Date().toISOString(), history:[...(request.history || []), createQuotationHistoryEntry(nextStatus, note || `${file.name} uploaded`)], adminUnread:false }; }); setQuotationRequestsAndRefresh(requests); closeQuotationUploadModal(); if(document.getElementById('quotationDetailBackdrop')?.classList.contains('open') && currentQuotationRequestId) openQuotationDetailModal(currentQuotationRequestId); showToast('Quotation PDF uploaded'); }
function sendQuotationForApproval(){ if(!currentUser?.isAdmin || !currentQuotationUploadRequestId) return; const selectedUserId=(document.getElementById('quotationApprovalUser')?.value || '').trim(); let blocked=false; let missingRecipient=false; const requests=getStoredQuotationRequests().map(request=>{ if(request.id!==currentQuotationUploadRequestId) return request; if(!request.quotationPdfData){ blocked=true; return request; } const recipient=getUserById(selectedUserId || request.approvalSalesUserId || request.salesUserId); if(!recipient){ missingRecipient=true; return request; } const nextStatus=request.status==='Correction Requested' ? 'Revised Quotation Sent' : 'Sent for Sales Approval'; return { ...request, status:nextStatus, updatedAt:new Date().toISOString(), adminUnread:false, approvalSalesUserId:recipient.userId, approvalSalesPerson:recipient.userId, salesUnreadFor:[normalizeUserId(recipient.userId)], history:[...(request.history || []), createQuotationHistoryEntry(nextStatus,`Quotation shared with ${recipient.userId} for approval`)] }; }); if(blocked){ showToast('Upload the quotation PDF first'); return; } if(missingRecipient){ showToast('Select a sales user for approval'); return; } setQuotationRequestsAndRefresh(requests); closeQuotationUploadModal(); if(document.getElementById('quotationDetailBackdrop')?.classList.contains('open') && currentQuotationRequestId) openQuotationDetailModal(currentQuotationRequestId); showToast('Quotation sent for sales approval'); }
function openQuotationCorrectionModal(requestId){ currentQuotationCorrectionRequestId=requestId; const remarks=document.getElementById('quotationCorrectionRemarks'); if(remarks) remarks.value=''; document.getElementById('quotationCorrectionBackdrop')?.classList.add('open'); }
function closeQuotationCorrectionModal(){ document.getElementById('quotationCorrectionBackdrop')?.classList.remove('open'); }
function submitQuotationCorrection(){ if(!currentQuotationCorrectionRequestId) return; const remarks=document.getElementById('quotationCorrectionRemarks')?.value.trim() || ''; if(!remarks){ showToast('Enter correction remarks'); return; } const now=new Date().toISOString(); const requests=getStoredQuotationRequests().map(request=>{ if(request.id!==currentQuotationCorrectionRequestId) return request; return { ...request, status:'Correction Requested', updatedAt:now, adminUnread:true, salesUnreadFor:[], correctionHistory:[...(request.correctionHistory || []), { at:now, by:currentUser?.userId || 'Sales', remarks }], history:[...(request.history || []), createQuotationHistoryEntry('Correction Requested', remarks)] }; }); setQuotationRequestsAndRefresh(requests); closeQuotationCorrectionModal(); if(document.getElementById('quotationDetailBackdrop')?.classList.contains('open') && currentQuotationRequestId) openQuotationDetailModal(currentQuotationRequestId); showToast('Correction requested'); }
function approveQuotationRequest(requestId){ const requests=getStoredQuotationRequests().map(request=>{ if(request.id!==requestId) return request; return { ...request, status:'Approved by Sales', updatedAt:new Date().toISOString(), adminUnread:true, salesUnreadFor:[], history:[...(request.history || []), createQuotationHistoryEntry('Approved by Sales','Sales approved the quotation')] }; }); setQuotationRequestsAndRefresh(requests); if(document.getElementById('quotationDetailBackdrop')?.classList.contains('open') && currentQuotationRequestId) openQuotationDetailModal(currentQuotationRequestId); showToast('Quotation approved'); }
function markQuotationCancelled(requestId){ if(!currentUser?.isAdmin) return; const requests=getStoredQuotationRequests().map(request=>{ if(request.id!==requestId) return request; return { ...request, status:'Cancelled', updatedAt:new Date().toISOString(), history:[...(request.history || []), createQuotationHistoryEntry('Cancelled','Request cancelled by admin')] }; }); setQuotationRequestsAndRefresh(requests); if(document.getElementById('quotationDetailBackdrop')?.classList.contains('open') && currentQuotationRequestId) openQuotationDetailModal(currentQuotationRequestId); showToast('Quotation request cancelled'); }
function renderAll(){
  updateKPI();
  renderBarChart();
  renderDonut();
  updateQuotationNotifications();
}
